"use client"

import { Table } from "@/registry/preskok/ui/preskok-ui/table"

const invoices = [
  {
    id: "INV001",
    invoice: "INV001",
    paymentStatus: "Paid",
    totalAmount: "$250.00",
    paymentMethod: "Credit Card",
  },
  {
    id: "INV002",
    invoice: "INV002",
    paymentStatus: "Pending",
    totalAmount: "$150.00",
    paymentMethod: "PayPal",
  },
  {
    id: "INV003",
    invoice: "INV003",
    paymentStatus: "Unpaid",
    totalAmount: "$350.00",
    paymentMethod: "Bank Transfer",
  },
]

const columns = [
  { id: "invoice", name: "Invoice" },
  { id: "paymentStatus", name: "Status" },
  { id: "paymentMethod", name: "Method" },
  { id: "totalAmount", name: "Amount" },
]

export default function TableDemo() {
  return (
    <Table aria-label="Invoices" rows={invoices} columns={columns}>
      <Table.Header>
        {(column) => (
          <Table.Column key={column.id} id={column.id}>
            {column.name}
          </Table.Column>
        )}
      </Table.Header>
      <Table.Body>
        {(row) => (
          <Table.Row key={row.id} id={row.id}>
            {(columnKey) => (
              <Table.Cell>{row[columnKey as keyof typeof row]}</Table.Cell>
            )}
          </Table.Row>
        )}
      </Table.Body>
    </Table>
  )
}
